55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const policyBaseOf = (items: Item[]): number =>
69	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
70	
71	// Keep this as `base + base * RATE`. The algebraically equivalent
72	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
73	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
74	// upward float error rather than absorbing it.
75	const quote = (items: Item[]): QuoteResult => {
76	  const policyBase = policyBaseOf(items);
77	
78	  return {
79	    premium: Math.ceil(
80	      policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
81	    ),
82	  };
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => ({
86	  results: scenario.steps.map((step) => quote((step as QuoteStep).items)),
87	});
